<template><main class="login"><a-card :bordered="false" class="login-card"><div class="title"><span>Q</span><div><h1>QMediaSync</h1><p>媒体同步与刮削管理平台</p></div></div><a-form layout="vertical" :model="form" @finish="submit"><a-form-item label="用户名" name="username" :rules="[{required:true,message:'请输入用户名'}]"><a-input v-model:value="form.username" size="large" placeholder="请输入用户名"/></a-form-item><a-form-item label="密码" name="password" :rules="[{required:true,message:'请输入密码'}]"><a-input-password v-model:value="form.password" size="large" placeholder="请输入密码"/></a-form-item><a-checkbox v-model:checked="form.rememberMe">记住我（30 天）</a-checkbox><a-button block type="primary" size="large" html-type="submit" :loading="loading">登录</a-button></a-form></a-card></main></template>
<script setup lang="ts">import{reactive,ref}from'vue';import{message}from'ant-design-vue';import{useRouter}from'vue-router';import{useSessionStore}from'../stores/session';const form=reactive({username:'',password:'',rememberMe:false}),loading=ref(false),session=useSessionStore(),router=useRouter();async function submit(){loading.value=true;try{await session.login(form.username,form.password,form.rememberMe);router.push('/dashboard')}catch(e){message.error(e instanceof Error?e.message:'登录失败')}finally{loading.value=false}}</script>
<style scoped>.login{min-height:100vh;display:grid;place-items:center;padding:20px;background:radial-gradient(circle at 10% 10%,#dfe6ff,transparent 35%),linear-gradient(135deg,#f8faff,#eef2fb)}.login-card{width:min(410px,100%);padding:18px;box-shadow:0 24px 70px rgba(41,53,93,.14)}.title{display:flex;align-items:center;gap:13px;margin-bottom:30px}.title>span{display:grid;place-items:center;width:48px;height:48px;border-radius:14px;background:linear-gradient(135deg,#5b6cf9,#8c5edc);color:#fff;font-size:27px;font-weight:800}.title h1{margin:0}.title p{margin:4px 0;color:#8b95a7}.ant-form{display:grid;gap:5px}</style>
